          const newNoteSecondary = "hsl(" + (_ColorConfig.c_noiseSecondaryNoteHue + channel * _ColorConfig.c_noiseSecondaryNoteHueScale / _ColorConfig.c_noiseChannelCountOverride * 256) % colorFormulaNoiseLimit + "," + (_ColorConfig.c_noiseSecondaryNoteSat + channel * _ColorConfig.c_noiseSecondaryNoteSatScale) + "%," + (_ColorConfig.c_noiseSecondaryNoteLum + channel * _ColorConfig.c_noiseSecondaryNoteLumScale) + "%)";
          const newNotePrimary = "hsl(" + (_ColorConfig.c_noisePrimaryNoteHue + channel * _ColorConfig.c_noisePrimaryNoteHueScale / _ColorConfig.c_noiseChannelCountOverride * 256) % colorFormulaNoiseLimit + "," + (_ColorConfig.c_noisePrimaryNoteSat + channel * _ColorConfig.c_noisePrimaryNoteSatScale) + "%," + (_ColorConfig.c_noisePrimaryNoteLum + channel * _ColorConfig.c_noisePrimaryNoteLumScale) + "%)";
