          const newNoteSecondary = "hsl(" + (_ColorConfig.c_modSecondaryNoteHue + channel * _ColorConfig.c_modSecondaryNoteHueScale / _ColorConfig.c_modChannelCountOverride * 256) % colorFormulaModLimit + "," + (_ColorConfig.c_modSecondaryNoteSat + channel * _ColorConfig.c_modSecondaryNoteSatScale) + "%," + (_ColorConfig.c_modSecondaryNoteLum + channel * _ColorConfig.c_modSecondaryNoteLumScale) + "%)";
          const newNotePrimary = "hsl(" + (_ColorConfig.c_modPrimaryNoteHue + channel * _ColorConfig.c_modPrimaryNoteHueScale / _ColorConfig.c_modChannelCountOverride * 256) % colorFormulaModLimit + "," + (_ColorConfig.c_modPrimaryNoteSat + channel * _ColorConfig.c_modPrimaryNoteSatScale) + "%," + (_ColorConfig.c_modPrimaryNoteLum + channel * _ColorConfig.c_modPrimaryNoteLumScale) + "%)";
