            const setting = this._doc.song.channels[this._doc.channel].instruments[this._doc.getCurrentInstrument(this._barOffset)].modulators[mod2];
            const presValue = this._cursor.curNote.pins[pinIdx].size + Config.modulators[setting].convertRealFactor;
            const xOffset = +(presValue >= 10) + +(presValue >= 100) + +(presValue < 0) + +(presValue <= -10);
            this._modDragValueLabelWidth = 8 + xOffset * 8;
